// Define the Complex struct as described in the problem
#[derive(Debug, Clone, PartialEq)]
struct Complex {
    real: i32,
    imag: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // First, check if all imaginary parts are "close to zero"
    let all_close = arr.iter().all(|c| {
        // Calculate tolerance * 2 as i64 to avoid overflow
        let threshold = tol as i64 * 2;
        // Check if |imag| ≤ threshold
        (c.imag as i64).abs() <= threshold
    });
    
    if all_close {
        // Create new array with imaginary parts set to 0
        arr.into_iter()
            .map(|c| Complex {
                real: c.real,
                imag: 0,
            })
            .collect()
    } else {
        // Return original array unchanged
        arr
    }
}